script.inlineScript:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    if (api.context.props.listTable == 'adaptive_auth_event') {
        return api.state.hideEmptyState;
    }
    return true;
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    if (api.context.session.user.roles.includes('sn_vsc.security_center_admin') || api.context.session.user.roles.includes('admin')) {
        return '[{"label":"Enable", "variant" : "primary"}]';
    } else {
        return '';
    }
}
